#include "project_files.h"
#include "../../platform/desktop/file_access.h"
#include <filesystem>
#include <vector>
#include <memory>
#include <cstdio>
using namespace groove;
int main(){DesktopFiles fs;auto p=std::make_unique<ProjectState>();bool first=true;printf("{\"files\":[");for(const char* root:{"assets/presets","assets/kits","assets/demo-projects","assets/validation","FACTORY"})if(std::filesystem::exists(root))for(const auto& f:std::filesystem::recursive_directory_iterator(root)){auto path=f.path().string();if(!f.is_regular_file() || !(f.path().extension()==".mgxs" || f.path().extension()==".mgxk" || f.path().extension()==".mgxp" || f.path().extension()==".mgx"))continue;bool ok=read_project_file(fs,path.c_str(),*p);if(!ok){fprintf(stderr,"Content decode failed %s\n",path.c_str());printf("%s{\"path\":\"%s\",\"decoded\":false}",first?"":",",path.c_str());first=false;continue;}bool engines[32]{},fx[kFxCount]{};auto sound=[&](const auto& s){unsigned id=unsigned(s.instrument);if(id<32)engines[id]=true;if(s.instrument==Instrument::DrumKit)for(const auto& pad:s.kit.pads)if(pad.insert_fx[0]>=0 && pad.insert_fx[0]<kFxCount)fx[unsigned(pad.insert_fx[0])]=true;};for(const auto& t:p->tracks){sound(t);if(t.instrument==Instrument::Layer)for(unsigned l=0;l<t.layer.count;++l)sound(t.layer.parts[l].sound);for(unsigned s=0;s<2;++s)fx[unsigned(t.insert_fx[s*4])]=true;}for(const auto& slot:p->sounds)if(slot.instrument!=Instrument::Empty){sound(slot);if(slot.instrument==Instrument::Layer)for(unsigned l=0;l<slot.layer.count;++l)sound(slot.layer.parts[l].sound);}for(const auto& g:p->routing.groups)for(unsigned i=0;i<2;++i)fx[unsigned(g.insert_fx[i*4])]=true;if(p->preset_fx.present)for(unsigned i=0;i<2;++i)fx[unsigned(p->preset_fx.inserts[i*4])]=true;
 printf("%s{\"path\":\"%s\",\"kind\":%u,\"engines\":[",first?"":",",path.c_str(),unsigned(p->content_kind));first=false;bool item=true;for(unsigned i=0;i<32;++i)if(engines[i]){printf("%s%u",item?"":",",i);item=false;}printf("],\"fx\":[");item=true;for(unsigned i=0;i<kFxCount;++i)if(fx[i]){printf("%s%u",item?"":",",i);item=false;}printf("]}");}printf("]}\n");}
